using VisualRelay.Core.Execution;

namespace VisualRelay.Tests;

public sealed class WorkspaceVolumeTempDirTests
{
    [Fact]
    public void ExternalVolume_PathUnderVolume_ReturnsTemporaryItems()
    {
        Assert.SkipUnless(OperatingSystem.IsMacOS(), "macOS-only /Volumes/ paradigm");

        var result = WorkspaceVolumeTempDir.Resolve("/Volumes/Tera/dev/x");

        Assert.Equal("/Volumes/Tera/.TemporaryItems", result);
    }

    [Fact]
    public void ExternalVolume_VolumeRoot_ReturnsTemporaryItems()
    {
        Assert.SkipUnless(OperatingSystem.IsMacOS(), "macOS-only /Volumes/ paradigm");

        var result = WorkspaceVolumeTempDir.Resolve("/Volumes/Tera");

        Assert.Equal("/Volumes/Tera/.TemporaryItems", result);
    }

    [Fact]
    public void HomeDirectory_ReturnsNull()
    {
        Assert.SkipUnless(OperatingSystem.IsMacOS(), "macOS-only /Volumes/ paradigm");

        var result = WorkspaceVolumeTempDir.Resolve("/Users/nick/dev/x");

        Assert.Null(result);
    }

    [Fact]
    public void SystemTemp_ReturnsNull()
    {
        Assert.SkipUnless(OperatingSystem.IsMacOS(), "macOS-only /Volumes/ paradigm");

        var result = WorkspaceVolumeTempDir.Resolve("/private/tmp/wt");

        Assert.Null(result);
    }

    [Fact]
    public void TrailingSlash_HandledGracefully()
    {
        Assert.SkipUnless(OperatingSystem.IsMacOS(), "macOS-only /Volumes/ paradigm");

        var result = WorkspaceVolumeTempDir.Resolve("/Volumes/Tera/dev/");

        Assert.Equal("/Volumes/Tera/.TemporaryItems", result);
    }

    [Fact]
    public void BareVolumes_ReturnsNull()
    {
        Assert.SkipUnless(OperatingSystem.IsMacOS(), "macOS-only /Volumes/ paradigm");

        var result = WorkspaceVolumeTempDir.Resolve("/Volumes");

        Assert.Null(result);
    }

    [Fact]
    public void [ENCRYPTED:fastly]6Zx2LsMAlxpg8ALsHg6Rm44UO0T6HKh2()
    {
        Assert.SkipUnless(OperatingSystem.IsMacOS(), "macOS-only /Volumes/ paradigm");

        var result = WorkspaceVolumeTempDir.Resolve("/Volumes/");

        Assert.Null(result);
    }

    [Fact]
    public void NonMacOS_AlwaysReturnsNull()
    {
        Assert.SkipUnless(!OperatingSystem.IsMacOS(), "non-macOS guard");

        // On any non-macOS platform, including paths that happen to
        // start with /Volumes/, the helper must return null.
        var result = WorkspaceVolumeTempDir.Resolve("/Volumes/Tera/dev/x");

        Assert.Null(result);
    }
}

namespace VisualRelay.Core.Execution;

/// <summary>
/// Pure path-string helper that resolves the workspace volume's temporary-items
/// directory for the nono sandbox grant. macOS Foundation atomic file writes
/// (<c>NSWriteAuxiliaryFile</c>) stage their temp file in the destination
/// volume's <c>.TemporaryItems</c> directory at the volume root — outside
/// <c>--allow-cwd</c> for external-volume workspaces — which causes EPERM on
/// every atomic write. This helper returns that directory so
/// <see cref="SwivalSubagentRunner.BuildNonoPrefix"/> can auto-grant it with
/// <c>-a &lt;dir&gt;</c>.
/// </summary>
internal static class WorkspaceVolumeTempDir
{
    /// <summary>
    /// Returns <c>/Volumes/&lt;vol&gt;/.TemporaryItems</c> when
    /// <paramref name="rootPath"/> lives under a mount point
    /// <c>/Volumes/&lt;non-empty-vol&gt;</c> on macOS; otherwise <c>null</c>.
    /// Pure path-string logic — no filesystem probing.
    /// </summary>
    internal static string? Resolve(string rootPath)
    {
        if (!OperatingSystem.IsMacOS())
            return null;

        // Normalise: trim trailing separators so e.g.
        //   /Volumes/Tera/  →  /Volumes/Tera
        var trimmed = rootPath.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);

        const string volumesPrefix = "/Volumes/";
        if (!trimmed.StartsWith(volumesPrefix, StringComparison.Ordinal))
            return null;

        // Extract the volume name between "/Volumes/" and the next '/' or EOS.
        var afterPrefix = trimmed.AsSpan(volumesPrefix.Length);
        var slashIdx = afterPrefix.IndexOf('/');

        var volumeName = slashIdx < 0
            ? afterPrefix
            : afterPrefix[..slashIdx];

        if (volumeName.IsEmpty)
            return null;

        return string.Create(
            volumesPrefix.Length + volumeName.Length + "/.TemporaryItems".Length,
            (volumesPrefix, volumeName),
            (span, state) =>
            {
                state.volumesPrefix.CopyTo(span);
                var pos = state.volumesPrefix.Length;
                state.volumeName.CopyTo(span[pos..]);
                pos += state.volumeName.Length;
                "/.TemporaryItems".CopyTo(span[pos..]);
            });
    }
}

